INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20305$nota-0089$m20305$, $m20306$Training and Racing with a Power Meter.pdf$m20306$, $m20307$229$m20307$, $m20308$a four- to six-week plateau in CTL during a time when the focus of training has not changed and performance is constant is generally evidence of training stagnation. Athletes in this situation might feel they are training well by being very consistent... but in fact this is not training at all. It is simply maintaining, because the overload principle is not being applied.$m20308$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20309$nota-0089$m20309$, $m20310$nota-0083$m20310$, $m20311$pre-requisito$m20311$, $m20312$usa o CTL definido na nota-0083$m20312$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20313$nota-0093$m20313$, $m20314$Training and Racing with a Power Meter.pdf$m20314$, $m20315$214$m20315$, $m20316$the vast majority has employed what is typically referred to as the 'impulse-response model,' first proposed by Dr. Eric Banister in 1975... Training is said to exert two opposing effects: (1) positive adaptations... (chronic), and (2) negative consequences of recent exercise bouts... (acute).$m20316$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20317$nota-0093$m20317$, $m20318$Training and Racing with a Power Meter.pdf$m20318$, $m20319$217$m20319$, $m20320$the impulse-response model assumes that there is no upper limit to performance... In reality, plateaus happen.$m20320$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20321$nota-0093$m20321$, $m20322$Training and Racing with a Power Meter.pdf$m20322$, $m20323$218$m20323$, $m20324$performance would have to be directly measured between 20 and 200 times in total... Banister himself suggested revisiting the fit of the model to the data every 60 to 90 days, which would mean directly measuring an athlete's maximal performance ability at least every fourth day... obviously unrealistic.$m20324$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20325$nota-0093$m20325$, $m20326$nota-0083$m20326$, $m20327$pre-requisito$m20327$, $m20328$o CTL/ATL/TSB (nota-0083, 0084, 0085) foram derivados como simplificação prática deste modelo$m20328$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20329$nota-0093$m20329$, $m20330$nota-0084$m20330$, $m20331$pre-requisito$m20331$, $m20332$ATL é um dos dois termos (junto com CTL/nota-0083) derivados como simplificação do modelo de Banister — citado no corpo da nota, link estrutural ausente até auditoria de 2026-08-02$m20332$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20333$nota-0093$m20333$, $m20334$nota-0085$m20334$, $m20335$pre-requisito$m20335$, $m20336$TSB (CTL-ATL) é o terceiro termo derivado como simplificação do modelo de Banister — citado no corpo da nota, link estrutural ausente até auditoria de 2026-08-02$m20336$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20337$nota-0095$m20337$, $m20338$Training and Racing with a Power Meter.pdf$m20338$, $m20339$267$m20339$, $m20340$Plan A is the plan Jill will follow if her race is on Saturday, while Plan B is the one she will use if the race is on Sunday. If she is just training through the weekend, she will follow Plan C.$m20340$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20341$nota-0095$m20341$, $m20342$Training and Racing with a Power Meter.pdf$m20342$, $m20343$268$m20343$, $m20344$If you are racing on Saturday/Plan A: Thursday should be an easy ride to give yourself a rest two days before your race. Friday will be a tune-up workout to prep your legs for the hard effort on race day. If you are racing on Sunday/Plan B: Thursday will be an Endurance ride. Don't overdo it, but include some short bursts to keep your legs sharp. Friday will be an Active Recovery day and Saturday is the tune-up day to get your legs prepped for the race. If you are not racing/Plan C: Thursday will be an Endurance ride, with some short bursts to keep the legs sharp. Friday is for Active Recovery riding and Saturday is a solid Tempo ride with some shorter efforts.$m20344$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20345$nota-0095$m20345$, $m20346$nota-0048$m20346$, $m20347$complementa$m20347$, $m20348$aplica os conceitos de zonas/tipos de treino já definidos, organizando-os na estrutura semanal conforme o calendário de provas$m20348$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20349$nota-0098$m20349$, $m20350$Training and Racing with a Power Meter.pdf$m20350$, $m20351$289$m20351$, $m20352$If you begin to feel that you are overly tired at the end of a hard week of training, it might be advantageous to move up a rest week. On the other side of the coin, it's okay to push back a scheduled rest week if you are not tired.$m20352$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20353$nota-0098$m20353$, $m20354$Training and Racing with a Power Meter.pdf$m20354$, $m20355$290$m20355$, $m20356$Many times athletes do not push themselves hard enough; as soon as they get a little tired, they assume they are overtraining. Push through these periods to avoid limiting your performance potential... Do be sure to take the rest week in the week after it was scheduled.$m20356$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20357$nota-0098$m20357$, $m20358$nota-0090$m20358$, $m20359$complementa$m20359$, $m20360$fornece a lógica qualitativa de ajuste de calendário que complementa os limites quantitativos de ramp rate de CTL (nota-0090) e o estado de overreaching (nota-0092)$m20360$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20361$nota-0098$m20361$, $m20362$nota-0092$m20362$, $m20363$complementa$m20363$, $m20364$sinal objetivo de overreaching (TSB muito negativo prolongado) citado no corpo da nota como forma de diferenciar 'fadiga normal a ser superada' de 'sinal real de overreaching' — link estrutural ausente até auditoria de 2026-08-02$m20364$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20365$nota-0099$m20365$, $m20366$Training and Racing with a Power Meter.pdf$m20366$, $m20367$289$m20367$, $m20368$Another common trap is the temptation to force the plan. Some athletes do this by 'stacking' workouts to make up for missed sessions... Stacking Level 4 work, a long group ride and hills, and sprints all in the same day is a recipe for disaster... Packing all or most of the work into a few days will lead to illness or injury. If you miss a day, it's generally better to move on to the next workout. One caveat: If the workout you missed was highly specific, and you see that you will not be performing that workout again for at least two weeks, then you should try to make up the workout as soon as possible.$m20368$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20369$nota-0099$m20369$, $m20370$nota-0092$m20370$, $m20371$causal$m20371$, $m20372$empilhar treinos perdidos é uma via direta para o estado de overreaching não funcional descrito na nota-0092$m20372$)
